/*
    LaunchProject - Texas MISA Fall 2026 Case Competition
    Script 04 of 06: shift-level planning data

    ALL VALUES ARE SIMULATED MOCK DATA FOR A STUDENT CASE COMPETITION. They are not Costco data and do not
    represent Costco wages, staffing levels, schedules, or service performance.

    Run after 01, 02 and 03. Rerunnable: clears its own rows first.

    Section A  Planning week (Thu 2026-02-12 .. Wed 2026-02-18) rows in the core [API]/[src]/[model] tables:
               DimCalendarDay (+7), DimHolidayDay (+7), FactDailyFeatures (+63, dataset_partition = 'test'),
               ModelRun (+1 naive benchmark), FactDailyPrediction (+63 naive benchmark forecast).
               No actual demand is loaded for the planning week - teams forecast it.
    Section B  [comp] reference / assumption tables.
    Section C  [comp] fact tables (historical shift grain + planning-week scenarios).
*/
SET NOCOUNT ON;
GO
USE [LaunchProject];
GO

BEGIN TRY
    BEGIN TRANSACTION;

    /* ---------- clear rows from any earlier run of this script (children first) ---------- */
    DELETE FROM [comp].[ScenarioDemandAdjustment];
    DELETE FROM [comp].[FactShiftServiceLevel];
    DELETE FROM [comp].[FactShiftAvailability];
    DELETE FROM [comp].[FactShiftSchedule];
    DELETE FROM [comp].[FactShiftDemand];
    DELETE FROM [comp].[Scenario];
    DELETE FROM [comp].[LaborCostAssumption];
    DELETE FROM [comp].[ServiceMetricDefinition];
    DELETE FROM [comp].[LaborStandard];
    DELETE FROM [comp].[ShiftDefinition];
    DELETE FROM [comp].[DimShift];
    DELETE FROM [src].[FactDailyPrediction] WHERE [model_run_id] = 2026021101;
    DELETE FROM [model].[ModelRun] WHERE [model_run_id] = 2026021101;
    DELETE FROM [API].[FactDailyFeatures] WHERE [day_date] >= '2026-02-12';
    DELETE FROM [API].[DimHolidayDay] WHERE [day_date] >= '2026-02-12';
    DELETE FROM [API].[DimCalendarDay] WHERE [day_date] >= '2026-02-12';

    /* ================= Section A: planning-week rows in core tables ================= */


    /* Planning-week features use the same formulas as the six-week history. Weather = planning-time forecast.
       Markdown fields use week-6 weekly sales as the planning basis because week-7 sales are not yet known. */

        [training_data_start], [training_data_end], [scoring_data_start], [scoring_data_end], [feature_set_name], [notes])
    VALUES (2026021101, N'Naive Same-Weekday Benchmark', N'comp-benchmark-1', N'Average of same weekday, weeks 3-6',
            '2026-02-11T18:00:00', '2026-02-11T18:05:00', '2026-01-15', '2026-02-11', '2026-02-12', '2026-02-18',
            N'none (calendar only)',
            N'Benchmark forecast for the planning week. Ignores holidays, promotions and weather. Teams are expected to beat it.');

    /* Naive benchmark: computed from the loaded history so it always agrees with it. */
    ;WITH hist AS (
        SELECT tl.[store_id], tl.[dept_id], c.[day_of_week],
               AVG(ta.[busyness_proxy]) AS avg_busy,
               AVG(tl.[transaction_count_proxy]) AS avg_tcp,
               AVG(tl.[traffic_index]) AS avg_ti
        FROM [API].[FactDailyTrainingLaborOutput] AS tl
        INNER JOIN [API].[FactDailyTargetAudit] AS ta
            ON ta.[store_id] = tl.[store_id] AND ta.[dept_id] = tl.[dept_id] AND ta.[day_date] = tl.[day_date]
        INNER JOIN [API].[DimCalendarDay] AS c ON c.[day_date] = tl.[day_date]
        WHERE c.[week_of_year] BETWEEN 3 AND 6
        GROUP BY tl.[store_id], tl.[dept_id], c.[day_of_week]
    ), fc AS (
        SELECT f.[store_id], f.[dept_id], f.[day_date],
               ROUND(h.avg_busy, 2) AS p_busy, ROUND(h.avg_tcp, 4) AS p_tcp, ROUND(h.avg_ti, 2) AS p_ti
        FROM [API].[FactDailyFeatures] AS f
        INNER JOIN [API].[DimCalendarDay] AS c ON c.[day_date] = f.[day_date]
        INNER JOIN hist AS h ON h.[store_id] = f.[store_id] AND h.[dept_id] = f.[dept_id] AND h.[day_of_week] = c.[day_of_week]
        WHERE f.[dataset_partition] = N'test'
    )
        [predicted_transaction_count_proxy], [predicted_traffic_index], [predicted_busyness_band], [predicted_labor_planning_context],
        [predicted_recommended_labor_band], [predicted_recommended_labor_band_code], [predicted_labor_rule_reason])
    SELECT 2026021101, fc.[store_id], fc.[dept_id], fc.[day_date], fc.p_busy, fc.p_tcp, fc.p_ti,
        CASE WHEN fc.p_ti < 25 THEN N'Low' WHEN fc.p_ti < 50 THEN N'Standard' WHEN fc.p_ti < 85 THEN N'High' ELSE N'Peak' END,
        CASE WHEN fc.p_ti >= 85 THEN N'Peak_Demand' WHEN fc.p_ti >= 50 THEN N'Standard_Day' ELSE N'Light_Day' END,
        CASE WHEN fc.p_ti < 25 THEN N'Minimal Coverage' WHEN fc.p_ti < 50 THEN N'Light Coverage' WHEN fc.p_ti < 85 THEN N'Standard Coverage'
             WHEN fc.p_ti < 100 THEN N'Add Flex Coverage' ELSE N'Peak Coverage' END,
        CASE WHEN fc.p_ti < 25 THEN 1 WHEN fc.p_ti < 50 THEN 2 WHEN fc.p_ti < 85 THEN 3 WHEN fc.p_ti < 100 THEN 4 ELSE 5 END,
        N'Naive benchmark: mean of the same weekday in weeks 3-6. Ignores holidays, promotions and weather.'
    FROM fc;

    /* ================= Section B: [comp] reference / assumption tables ================= */






    /* ================= Section C: [comp] fact tables ================= */















    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO

SELECT 'comp.FactShiftDemand' AS table_name, COUNT(*) AS row_count FROM [comp].[FactShiftDemand]
UNION ALL SELECT 'comp.FactShiftSchedule (Actual)', COUNT(*) FROM [comp].[FactShiftSchedule] WHERE [schedule_type] = N'Actual'
UNION ALL SELECT 'comp.FactShiftSchedule (Draft)', COUNT(*) FROM [comp].[FactShiftSchedule] WHERE [schedule_type] = N'Draft'
UNION ALL SELECT 'comp.FactShiftAvailability', COUNT(*) FROM [comp].[FactShiftAvailability]
UNION ALL SELECT 'comp.FactShiftServiceLevel', COUNT(*) FROM [comp].[FactShiftServiceLevel]
UNION ALL SELECT 'comp.ScenarioDemandAdjustment', COUNT(*) FROM [comp].[ScenarioDemandAdjustment]
UNION ALL SELECT 'API.FactDailyFeatures (test)', COUNT(*) FROM [API].[FactDailyFeatures] WHERE [dataset_partition] = N'test'
UNION ALL SELECT 'src.FactDailyPrediction (benchmark)', COUNT(*) FROM [src].[FactDailyPrediction] WHERE [model_run_id] = 2026021101;
GO
